import React, { useEffect, useState } from "react";

const AgentDownload = () => {
  const [userToken, setUserToken] = useState("");
  const [serverIP, setServerIP] = useState("");

  useEffect(() => {
    setUserToken(localStorage.getItem("userToken") || "YOUR_API_TOKEN");
    setServerIP(localStorage.getItem("serverIP") || "YOUR_SERVER_IP");
  }, []);

  return (
    <div className="p-6 max-w-4xl mx-auto bg-white dark:bg-gray-900 text-gray-800 dark:text-gray-100 rounded-xl shadow-md space-y-6">
      <h2 className="text-3xl font-bold text-blue-600 dark:text-blue-400">✅ Download and Install the OptiWeb Monitoring Agent</h2>
      <p className="text-lg">Follow these steps to set up the monitoring agent on your server:</p>

      {/* Step 1 */}
      <div>
        <h3 className="text-xl font-semibold text-green-600">1️⃣ Download the Agent</h3>
        <p className="mt-1">Run this command on your server:</p>
        <pre className="bg-gray-200 dark:bg-gray-800 p-3 rounded overflow-x-auto">
          wget --no-check-certificate https://optiweb.lankapanel.net/static/agent.py -O agent.py
        </pre>
      </div>

      {/* Step 2 */}
      <div>
        <h3 className="text-xl font-semibold text-green-600">2️⃣ Install Required Python Dependencies</h3>
        <p>Install necessary libraries:</p>
        <pre className="bg-gray-200 dark:bg-gray-800 p-3 rounded overflow-x-auto">
          pip install psutil requests
        </pre>
        <p className="mt-2">💡 Optionally, create a virtual environment:</p>
        <pre className="bg-gray-200 dark:bg-gray-800 p-3 rounded overflow-x-auto">
{`python3 -m venv optiweb_env
source optiweb_env/bin/activate`}
        </pre>
      </div>

      {/* Step 3 */}
      <div>
        <h3 className="text-xl font-semibold text-green-600">3️⃣ Create Configuration File</h3>
        <p>Create a file named <code>config.json</code> in the same folder as <code>agent.py</code>:</p>
        <pre className="bg-gray-200 dark:bg-gray-800 p-3 rounded overflow-x-auto">nano config.json</pre>
        <p>Paste this content:</p>
        <pre className="bg-gray-200 dark:bg-gray-800 p-3 rounded overflow-x-auto">
{`{
  "backend_api": "http://203.143.13.21:8000/api/auth/metrics/",
  "web_server_ip": "${serverIP}",
  "token": "${userToken}"
}`}
        </pre>
        <p className="mt-1">✅ Replace values with your actual <strong>server IP</strong> and <strong>API token</strong> if not pre-filled.</p>
      </div>

      {/* Step 4 */}
      <div>
        <h3 className="text-xl font-semibold text-green-600">4️⃣ Run the Agent (Foreground)</h3>
        <p>Start the agent to view logs live:</p>
        <pre className="bg-gray-200 dark:bg-gray-800 p-3 rounded overflow-x-auto">python3 agent.py</pre>
        <p className="mt-2">🔁 The agent sends data every 60 seconds in an infinite loop.</p>

        <p className="mt-4">📍 To run in the background (optional):</p>
        <pre className="bg-gray-200 dark:bg-gray-800 p-3 rounded overflow-x-auto">
          nohup python3 agent.py &gt; agent.log 2&gt;&amp;1 &amp;
        </pre>
        <p className="mt-2">Check logs later using:</p>
        <pre className="bg-gray-200 dark:bg-gray-800 p-3 rounded overflow-x-auto">tail -f agent.log</pre>
      </div>

      {/* Step 5 */}
      <div>
        <h3 className="text-xl font-semibold text-green-600">✅ 5️⃣ Verify in Dashboard</h3>
        <p className="mt-1">After a few minutes, your server metrics should appear under:</p>
        <ul className="list-disc list-inside ml-4 space-y-1">
          <li>🔍 <strong>Monitoring</strong></li>
          <li>⚠️ <strong>ML Prediction</strong></li>
          <li>🧾 <strong>Logs</strong></li>
          <li>🔌 <strong>Service Status</strong></li>
        </ul>
      </div>

      {/* Help Section */}
      <div>
        <h3 className="text-xl font-semibold text-red-500">❓ Need Help?</h3>
        <p className="mt-1">Email: <a href="mailto:chameerahetti1998@gmail.com" className="text-blue-500 hover:underline">chameerahetti1998@gmail.com</a></p>
        <p>Or check the dashboard for the FAQ/help section.</p>
      </div>
    </div>
  );
};

export default AgentDownload;
